import sys
import types

NS = types.SimpleNamespace
INCIDENT = "Checkout latency tripled at 14:05 UTC. Find the cause."
TOOLS = [{"name": "query_logs", "description": "Search service logs.",
          "input_schema": {"type": "object",
                           "properties": {"query": {"type": "string"}},
                           "required": ["query"]}}]
_THINKING = NS(type="thinking", thinking="", signature="EqQBCgIYAhIM1gbcDa9GJwZA...")
_MODIFIED = ("400 invalid_request_error: `thinking` or `redacted_thinking` blocks "
             "in the latest assistant message cannot be modified")


def run_tools(reply):
    return [{"type": "tool_result", "tool_use_id": b.id, "content": "p99 3.1s after deploy 4411"}
            for b in reply.content if b.type == "tool_use"]


def shorten_old_tool_results(messages, limit):
    for message in messages:
        if isinstance(message["content"], list):
            for block in message["content"]:
                if isinstance(block, dict) and block.get("type") == "tool_result":
                    block["content"] = block["content"][:limit]


def _create(*, model, max_tokens, tools, messages, **kwargs):
    if len(messages) == 1:
        call = NS(type="tool_use", id="toolu_01", name="query_logs",
                  input={"query": "checkout latency 14:00-14:10"})
        return NS(content=[_THINKING, call], stop_reason="tool_use")
    if _THINKING not in messages[-2]["content"]:
        print(_MODIFIED)
        raise SystemExit(0)
    answer = NS(type="text", text="Deploy 4411 added a blocking call in checkout.")
    return NS(content=[NS(type="thinking", thinking="", signature="EosnCkYI..."), answer],
              stop_reason="end_turn")


class _Anthropic:
    def __init__(self, **kwargs):
        self.messages = NS(create=_create)


sys.modules["anthropic"] = NS(Anthropic=_Anthropic)
